// Generated by scripts/build-mcp-view.mjs from mcp-view.html. Edit the HTML, then run npm run mcp:view.
export const MCP_VIEW_HTML = "<!doctype html>\n<!--\n  Gus's card inside Claude (MCP Apps, io.modelcontextprotocol/ui). One view for every tool: it\n  reads the tool's structuredContent and draws the city list, one city, the deals, Gus's answer\n  or a call in progress. Taps call the same MCP tools back through the host. No SDK; the\n  postMessage JSON-RPC is small enough to speak by hand. __ORIGIN__ is filled in by mcp.ts, and\n  `npm run mcp:view` turns this file into mcp-view.gen.ts.\n-->\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<style>\n@font-face { font-family: \"Wanted Display\"; font-weight: 700; src: local(\"SF Pro Rounded Bold\"), url(\"__ORIGIN__/fonts/WantedRounded-700.woff2\") format(\"woff2\"); }\n@font-face { font-family: \"Wanted Display\"; font-weight: 800; src: local(\"SF Pro Rounded Heavy\"), url(\"__ORIGIN__/fonts/WantedRounded-800.woff2\") format(\"woff2\"); }\n:root {\n  --display: ui-rounded, \"Wanted Display\", system-ui, sans-serif;\n  --body: -apple-system, BlinkMacSystemFont, \"SF Pro Text\", system-ui, sans-serif;\n  --paper: #EFE9DD; --card: #FFFFFF; --ink: #15130F; --ink-2: #6B675F; --ink-3: #A29E95; --line: rgba(20, 16, 8, 0.08);\n  --veil: rgba(20, 16, 8, 0.05);\n  --wanted: #FF5A1F; --wanted-text: #C2410C; --wanted-tint: #FFE9DF;\n  --ok: #1F9D63; --ok-tint: #E3F4EA; --ok-text: #0B6E49;\n  --ask-tint: #FDF2D3; --ask-text: #855C00; --sky-tint: #E2EEFA; --sky-text: #2459B8;\n  --shadow: 0 1px 2px rgba(60, 40, 0, 0.05), 0 12px 32px -12px rgba(60, 40, 0, 0.18);\n  --rim: inset 0 1px 0 rgba(255, 255, 255, 0.9);\n  --ease: cubic-bezier(0.22, 1, 0.36, 1);\n  color-scheme: light;\n}\n:root[data-theme=\"dark\"] {\n  --paper: #171612; --card: #22211C; --ink: #F3EFE6; --ink-2: #A8A397; --ink-3: #6E6A61; --line: rgba(255, 248, 230, 0.08);\n  --veil: rgba(255, 248, 230, 0.06);\n  --wanted-text: #FF8A4C; --wanted-tint: rgba(255, 90, 31, 0.16);\n  --ok-tint: rgba(31, 157, 99, 0.18); --ok-text: #5FD39C;\n  --ask-tint: rgba(242, 183, 5, 0.16); --ask-text: #F2C94C; --sky-tint: rgba(58, 123, 242, 0.18); --sky-text: #8DB4FF;\n  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 12px 32px -12px rgba(0, 0, 0, 0.6);\n  --rim: inset 0 1px 0 rgba(255, 255, 255, 0.05);\n  color-scheme: dark;\n}\n* { box-sizing: border-box; margin: 0; padding: 0; }\nhtml, body { background: transparent; }\nbody { font: 400 14px/1.4 var(--body); color: var(--ink); -webkit-font-smoothing: antialiased; }\nbutton { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; -webkit-tap-highlight-color: transparent; }\n.sheet { background: var(--paper); border-radius: 22px; padding: 14px; overflow: hidden; }\n\n/* who's talking */\n.top { display: flex; align-items: center; gap: 9px; margin-bottom: 12px; }\n.top img { width: 30px; height: 30px; border-radius: 9px; box-shadow: 0 2px 6px -2px rgba(255, 90, 31, 0.6); }\n.top b { font: 700 14px var(--display); display: block; }\n.top span { font-size: 12px; color: var(--ink-2); }\n.top .open { margin-left: auto; font: 700 12.5px var(--display); color: var(--wanted-text); padding: 6px 10px; border-radius: 99px; background: var(--wanted-tint); }\n\nh1 { font: 800 21px/1.15 var(--display); letter-spacing: -0.01em; margin: 2px 2px 10px; }\n.kicker { font: 700 11px var(--display); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-3); margin: 14px 4px 7px; }\n.card { background: var(--card); border-radius: 16px; box-shadow: var(--shadow), var(--rim); }\n.view { animation: rise 420ms var(--ease) both; }\n/* Slide only: a frame that never gets to animate still shows the card. */\n@keyframes rise { from { transform: translateY(8px); } }\n\n/* city list */\n.rows { padding: 4px 0; }\n.row { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; padding: 10px 14px; transition: background 160ms var(--ease); }\n.row + .row { border-top: 1px solid var(--line); }\n.row:active, .row:hover { background: var(--veil); }\n.rank { flex: none; width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; font: 800 13px var(--display); background: var(--veil); color: var(--ink-2); }\n.row.top3 .rank { background: var(--wanted); color: #fff; }\n.row .what { flex: 1; min-width: 0; }\n.row .what b { font: 700 16px var(--display); display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.row .what span { font-size: 12.5px; color: var(--ink-2); }\n.row .what .sleeper { color: var(--wanted-text); font-weight: 600; }\n.sig { flex: none; text-align: right; font: 700 13px var(--display); }\n.sig small { display: block; font: 500 11px var(--body); color: var(--ink-3); }\n.bar { width: 54px; height: 4px; border-radius: 9px; background: var(--veil); margin-top: 4px; overflow: hidden; }\n.bar i { display: block; height: 100%; border-radius: inherit; background: var(--wanted); }\n.chev { flex: none; color: var(--ink-3); font-size: 18px; }\n\n/* one city */\n.back { font: 700 13px var(--display); color: var(--ink-2); padding: 2px 4px 8px; }\n.big { padding: 16px; display: flex; align-items: center; gap: 14px; }\n.big .n { font: 800 34px/1 var(--display); letter-spacing: -0.02em; }\n.big .n small { font-size: 16px; color: var(--ink-3); }\n.big p { font-size: 13px; color: var(--ink-2); }\n.big .bar { width: 100%; height: 6px; margin-top: 8px; }\n.big img { width: 64px; height: 64px; flex: none; }\n.chips { display: flex; flex-wrap: wrap; gap: 6px; }\n.chip { font: 700 13px var(--display); padding: 7px 11px; border-radius: 99px; background: var(--card); box-shadow: var(--shadow), var(--rim); }\n.chip:first-child { background: var(--wanted); color: #fff; }\n.room { padding: 11px 14px; display: flex; align-items: center; gap: 10px; }\n.room + .room { border-top: 1px solid var(--line); }\n.room .what { flex: 1; min-width: 0; }\n.room b { font: 700 15px var(--display); display: block; }\n.room span { font-size: 12px; color: var(--ink-2); }\n.days { display: flex; gap: 3px; flex: none; }\n.days i { width: 15px; height: 17px; border-radius: 5px; font: 700 9.5px/17px var(--display); text-align: center; font-style: normal; background: var(--veil); color: var(--ink-3); }\n.days i.on { background: var(--ok-tint); color: var(--ok-text); }\n\n/* buttons */\n.cta { display: block; width: 100%; margin-top: 12px; padding: 13px 16px; border-radius: 14px; font: 800 15px var(--display); color: #fff;\n  background: linear-gradient(#FF7A3D, #F0500F); box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35), 0 8px 18px -8px rgba(255, 90, 31, 0.8); transition: transform 160ms var(--ease), opacity 160ms var(--ease); }\n.cta:active { transform: scale(0.98); }\n.cta.quiet { background: var(--card); color: var(--ink); box-shadow: var(--shadow), var(--rim); }\n.cta[disabled] { opacity: 0.6; }\n\n/* deals */\n.deal { padding: 14px; position: relative; }\n.deal + .deal { margin-top: 10px; }\n.deal b { font: 800 17px var(--display); display: block; padding-right: 110px; }\n.deal .city { font-size: 12.5px; color: var(--ink-2); }\n.stamp { position: absolute; top: 12px; right: 12px; font: 800 11.5px var(--display); padding: 5px 9px; border-radius: 8px; transform: rotate(2deg); }\n.st-waiting { background: var(--ask-tint); color: var(--ask-text); }\n.st-held { background: var(--ok-tint); color: var(--ok-text); }\n.st-talking { background: var(--sky-tint); color: var(--sky-text); }\n.terms { display: flex; gap: 6px; margin-top: 10px; flex-wrap: wrap; }\n.terms span { font: 700 12.5px var(--display); padding: 5px 9px; border-radius: 8px; background: var(--veil); }\n.letter { margin-top: 10px; font-size: 13px; color: var(--ink-2); font-style: italic; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n\n/* Gus answering */\n.say { display: flex; gap: 10px; align-items: flex-end; }\n.say img { width: 76px; height: 76px; flex: none; margin-bottom: -4px; }\n.bubble { flex: 1; padding: 13px 15px; border-radius: 18px 18px 18px 6px; font: 700 16.5px/1.3 var(--display); }\n.checked { padding: 4px 0; }\n.step { display: flex; gap: 10px; padding: 9px 14px; align-items: flex-start; }\n.step + .step { border-top: 1px solid var(--line); }\n.step i { flex: none; width: 18px; height: 18px; border-radius: 50%; background: var(--ok); color: #fff; font: 800 11px/18px var(--display); text-align: center; font-style: normal; margin-top: 1px; }\n.step b { font: 700 13.5px var(--display); display: block; }\n.step span { font-size: 12.5px; color: var(--ink-2); }\n\n/* waiting and calling */\n.wait { display: flex; align-items: center; gap: 12px; padding: 18px 6px; }\n.wait img { width: 64px; height: 64px; }\n.wait b { font: 800 17px var(--display); display: block; }\n.wait span { color: var(--ink-2); font-size: 13px; }\n.dots i { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--wanted); margin-right: 4px; animation: dot 1.2s var(--ease) infinite; }\n.dots i:nth-child(2) { animation-delay: 160ms; } .dots i:nth-child(3) { animation-delay: 320ms; }\n@keyframes dot { 0%, 100% { opacity: 0.25; } 40% { opacity: 1; } }\n.stage { display: block; font-size: 11.5px; color: var(--ink-3); margin-top: 4px; }\n.note { font-size: 12.5px; color: var(--ink-2); margin: 10px 4px 0; }\n@media (prefers-reduced-motion: reduce) { *, *::before { animation: none !important; transition: none !important; } }\n</style>\n</head>\n<body>\n<div class=\"sheet\" id=\"app\">\n  <div class=\"top\">\n    <img src=\"__ORIGIN__/icon.png\" alt=\"\" />\n    <div><b>Gus</b><span id=\"who\">Your tour manager</span></div>\n    <button class=\"open\" id=\"open\">Open in Wanted ↗</button>\n  </div>\n  <div id=\"body\"><div class=\"wait view\"><img src=\"__ORIGIN__/art/gus-thinking.webp\" alt=\"\" /><div><b>Looking it up</b><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"stage\" id=\"stage\">Connecting to Claude</span></div></div></div>\n</div>\n<script>\n(() => {\n  const ORIGIN = '__ORIGIN__';\n  const $ = (s) => document.querySelector(s);\n  const esc = (s) => String(s ?? '').replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' })[c]);\n  const art = (name) => ORIGIN + '/art/' + name + '.webp';\n  const state = { act: 'maya-ortiz', name: null, back: null, data: null };\n\n  // ---- JSON-RPC over postMessage with the host\n  let nextId = 1;\n  const pending = new Map();\n  const on = {};\n  window.addEventListener('message', (e) => {\n    if (e.source !== window.parent) return;\n    const m = e.data;\n    if (!m || m.jsonrpc !== '2.0') return;\n    if (m.id != null && pending.has(m.id) && !m.method) {\n      const p = pending.get(m.id);\n      pending.delete(m.id);\n      m.error ? p.reject(m.error) : p.resolve(m.result);\n    } else if (m.method) {\n      const r = on[m.method]?.(m.params || {});\n      if (m.id != null) window.parent.postMessage({ jsonrpc: '2.0', id: m.id, result: r || {} }, '*');\n    }\n  });\n  const request = (method, params) => new Promise((resolve, reject) => {\n    const id = nextId++;\n    pending.set(id, { resolve, reject });\n    window.parent.postMessage({ jsonrpc: '2.0', id, method, params }, '*');\n  });\n  const notify = (method, params) => window.parent.postMessage({ jsonrpc: '2.0', method, params }, '*');\n\n  function theme(ctx) {\n    if (!ctx) return;\n    if (ctx.theme) document.documentElement.dataset.theme = ctx.theme;\n  }\n  const openLink = (url) => request('ui/open-link', { url }).catch(() => window.open(url, '_blank'));\n  const appUrl = () => ORIGIN + '/a/' + state.act;\n  $('#open').onclick = () => openLink(appUrl());\n\n  async function call(name, args, waitText) {\n    wait(waitText);\n    try {\n      const r = await request('tools/call', { name, arguments: { act: state.act, ...args } });\n      show(r);\n    } catch (e) {\n      oops('That didn’t come back. Try again in a moment.');\n    }\n  }\n\n  // ---- views\n  const body = $('#body');\n  const paint = (html) => { body.innerHTML = '<div class=\"view\">' + html + '</div>'; };\n  const wait = (text) => paint('<div class=\"wait\"><img src=\"' + art('gus-working') + '\" alt=\"\" /><div><b>' + esc(text || 'Looking it up') + '</b><span class=\"dots\"><i></i><i></i><i></i></span></div></div>');\n  const oops = (text) => paint('<div class=\"wait\"><img src=\"' + art('gus-oops') + '\" alt=\"\" /><div><b>' + esc(text) + '</b></div></div>');\n  const pct = (n) => n == null ? '' : 'Hotter than ' + Math.min(99, n) + '% of US cities';\n\n  function cities(d) {\n    const rows = d.cities.map((c, i) => {\n      // The rank already says how strong; the line under it says what's happening there.\n      const sub = (c.sleeper ? '<span class=\"sleeper\">Sleeper · </span>' : '') + '<span>' + (c.posterUp ? (c.signatures >= 50 ? 'Poster full, asking rooms' : 'Poster up') : c.sleeper ? 'more fans than its size' : 'No poster yet') + '</span>';\n      const sig = c.posterUp\n        ? '<div class=\"sig\">' + c.signatures + '<small>of 50 signed</small><div class=\"bar\"><i style=\"width:' + Math.min(100, c.signatures * 2) + '%\"></i></div></div>'\n        : '<span class=\"chev\">›</span>';\n      return '<button class=\"row' + (i < 3 ? ' top3' : '') + '\" data-city=\"' + esc(c.id) + '\"><span class=\"rank\">' + c.rank + '</span><span class=\"what\"><b>' + esc(c.city) + '</b>' + sub + '</span>' + sig + '</button>';\n    }).join('');\n    paint('<h1>Where your crowd already is</h1><div class=\"card rows\">' + rows + '</div><p class=\"note\">From Qloo’s taste data, measured against other acts so big cities don’t win on size. Tap a city.</p>');\n    body.querySelectorAll('[data-city]').forEach((b) => b.onclick = () => { state.back = d; call('city_brief', { city: b.dataset.city }, 'Opening ' + b.querySelector('b').textContent.split(',')[0]); });\n  }\n\n  const DAYS = [['monday', 'M'], ['tuesday', 'T'], ['wednesday', 'W'], ['thursday', 'T'], ['friday', 'F'], ['saturday', 'S'], ['sunday', 'S']];\n  function city(d) {\n    const back = state.back ? '<button class=\"back\" id=\"back\">‹ All cities</button>' : '';\n    const s = d.signatures || 0;\n    const head = '<div class=\"card big\"><img src=\"' + art(s >= 50 ? 'badge-fifty' : 'pin-city') + '\" alt=\"\" /><div style=\"flex:1\"><div class=\"n\">' + s + ' <small>of 50</small></div><p>' + (s ? 'fans signed the WANTED poster here.' : 'No poster up yet. Gus can put one up.') + (d.heatPercentile != null ? ' ' + esc(pct(d.heatPercentile)) + '.' : '') + '</p><div class=\"bar\"><i style=\"width:' + Math.min(100, s * 2) + '%\"></i></div></div></div>';\n    const hoods = d.neighborhoods.length ? '<div class=\"kicker\">Where your crowd lives</div><div class=\"chips\">' + d.neighborhoods.map((h) => '<span class=\"chip\">' + esc(h) + '</span>').join('') + '</div>' : '';\n    const rooms = d.rooms.length ? '<div class=\"kicker\">Rooms that fit you</div><div class=\"card\">' + d.rooms.map((r) => {\n      const open = r.openDays ? new Set(r.openDays.map((x) => String(x).toLowerCase())) : null;\n      const days = open ? '<span class=\"days\">' + DAYS.map(([k, l]) => '<i class=\"' + (open.has(k) ? 'on' : '') + '\">' + l + '</i>').join('') + '</span>' : '';\n      return '<div class=\"room\"><span class=\"what\"><b>' + esc(r.name) + '</b><span>' + esc([r.neighborhood, r.size].filter(Boolean).join(' · ')) + '</span></span>' + days + '</div>';\n    }).join('') + '</div>' : '<p class=\"note\">No rooms that fit here yet.</p>';\n    const ask = d.rooms[0] ? '<button class=\"cta\" id=\"ask\">Send Gus to ask ' + esc(d.rooms[0].name) + '</button>' : '';\n    paint(back + '<h1>' + esc(d.cityName || d.city) + '</h1>' + head + hoods + rooms + ask);\n    if (state.back) $('#back').onclick = () => { const b = state.back; state.back = null; cities(b); };\n    if (d.rooms[0]) $('#ask').onclick = () => call('ask_rooms', { city: d.city, room: d.rooms[0].id }, 'Calling ' + d.rooms[0].name);\n  }\n\n  const STAMP = { waiting: 'Needs your yes', held: 'Booked', talking: 'Talking', declined: 'You passed' };\n  const when = (iso) => { const t = new Date(iso + 'T12:00:00'); return isNaN(t) ? iso : t.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' }); };\n  const ORDER = { waiting: 0, talking: 1, held: 2, declined: 3 };\n  function deals(d) {\n    const all = d.deals.slice().sort((a, b) => (ORDER[a.status] ?? 9) - (ORDER[b.status] ?? 9));\n    const more = all.length - 4;\n    d = { ...d, deals: all.slice(0, 4) };\n    if (!d.deals.length) return paint('<h1>No dates in talks</h1><p class=\"note\">Ask Gus to try a room in one of your cities.</p>');\n    const cards = d.deals.map((x) => {\n      const terms = [x.split != null ? x.split + '% of ticket sales' : null, x.deposit != null ? '$' + x.deposit + ' deposit' : null, x.date ? when(x.date) : null].filter(Boolean).map((t) => '<span>' + esc(t) + '</span>').join('');\n      return '<div class=\"card deal\"><span class=\"stamp st-' + esc(x.status) + '\">' + esc(STAMP[x.status] || x.status) + '</span><b>' + esc(x.room) + '</b><span class=\"city\">' + esc(x.city) + '</span>' + (terms ? '<div class=\"terms\">' + terms + '</div>' : '') + (x.status === 'talking' && x.lastLetter ? '<p class=\"letter\">“' + esc(x.lastLetter) + '”</p>' : '') + '</div>';\n    }).join('');\n    const yes = d.deals.some((x) => x.status === 'waiting');\n    paint('<h1>Dates Gus is working on</h1>' + cards + (more > 0 ? '<p class=\"note\">And ' + more + ' more in the app.</p>' : '') + '<button class=\"cta' + (yes ? '' : ' quiet') + '\" id=\"go\">' + (yes ? 'Say yes in Wanted' : 'See them in Wanted') + '</button><p class=\"note\">Nothing gets paid from here. You approve the exact offer in the app.</p>');\n    $('#go').onclick = () => openLink(appUrl());\n  }\n\n  const MOOD = { proud: 'gus-proud', thinking: 'gus-thinking', unimpressed: 'gus-waiting', idle: 'gus-idle' };\n  function gus(d) {\n    const steps = (d.steps || []).filter((s) => s.status === 'done');\n    const checked = steps.length ? '<div class=\"kicker\">What I checked</div><div class=\"card checked\">' + steps.map((s) => '<div class=\"step\"><i>✓</i><div><b>' + esc(s.label) + '</b>' + (s.found ? '<span>' + esc(s.found) + '</span>' : '') + '</div></div>').join('') + '</div>' : '';\n    const a = d.action;\n    const act = a && ['city', 'deal', 'link'].includes(a.type) ? '<button class=\"cta\" id=\"act\">' + esc(a.label) + '</button>' : '';\n    paint('<div class=\"say\"><img src=\"' + art(MOOD[d.mood] || 'gus-idle') + '\" alt=\"\" /><div class=\"card bubble\">' + esc(d.reply) + '</div></div>' + checked + act);\n    if (act) $('#act').onclick = () =>\n      a.type === 'city' ? call('city_brief', { city: a.id }, 'Opening ' + a.name)\n      : a.type === 'deal' ? call('ask_rooms', { city: a.id, room: a.roomId }, 'Calling the room')\n      : openLink(a.url);\n  }\n\n  function calling(d) {\n    const x = d.deal;\n    paint('<div class=\"wait\"><img src=\"' + art('gus-phone') + '\" alt=\"\" /><div><b>Calling ' + esc(x.room) + '</b><span>' + esc(x.city) + ' </span><span class=\"dots\"><i></i><i></i><i></i></span></div></div><p class=\"note\">He’ll stay inside your limits on the door and the deposit. Nothing gets paid until you say yes on the exact offer.</p><button class=\"cta\" id=\"go\">Watch the call in Wanted</button>');\n    $('#go').onclick = () => openLink(appUrl());\n  }\n\n  function show(r) {\n    if (!r) return;\n    const d = r.structuredContent;\n    if (r.isError || !d) return oops((r.content && r.content[0] && r.content[0].text) || 'Gus hit a snag.');\n    if (d.act) state.act = d.act;\n    if (d.actName) $('#who').textContent = d.actName + '’s tour manager';\n    ({ cities, city, deals, gus, calling })[d.view]?.(d);\n  }\n\n  // Which step we're on, so a stuck card says where it stuck.\n  const stage = (t) => { const el = document.getElementById('stage'); if (el) el.textContent = t; };\n  let args = null, got = false, toolName = null;\n  on['ui/notifications/tool-input'] = (p) => { args = p.arguments || {}; if (args.act) state.act = args.act; stage('Waiting for Gus’s answer'); };\n  on['ui/notifications/tool-result'] = (r) => { got = true; show(r); };\n  on['ui/notifications/tool-cancelled'] = () => oops('Stopped.');\n  on['ui/notifications/host-context-changed'] = theme;\n  on['ui/resource-teardown'] = () => ({});\n\n  new ResizeObserver(() => notify('ui/notifications/size-changed', { width: document.documentElement.scrollWidth, height: document.documentElement.scrollHeight })).observe(document.body);\n\n  if (window.matchMedia('(prefers-color-scheme: dark)').matches) document.documentElement.dataset.theme = 'dark';\n  // Say hello until Claude answers (a frame can load before the host is listening).\n  let hello = false;\n  const init = (tries) => {\n    request('ui/initialize', {\n      protocolVersion: '2026-01-26',\n      appInfo: { name: 'gus-card', version: '1.1.0' },\n      appCapabilities: { availableDisplayModes: ['inline'] },\n    }).then((r) => {\n      if (hello) return;\n      hello = true;\n      const ctx = (r && r.hostContext) || {};\n      theme(ctx);\n      toolName = ctx.toolInfo && ctx.toolInfo.tool && ctx.toolInfo.tool.name;\n      notify('ui/notifications/initialized', {});\n      stage('Waiting for Gus’s answer');\n      // If the result never comes through, ask Gus for it ourselves.\n      setTimeout(() => { if (!got && toolName) { stage('Asking Gus directly'); call(toolName, args || {}, 'Looking it up'); } }, 5000);\n    }, (e) => stage('Claude said no: ' + ((e && e.message) || 'unknown')));\n    setTimeout(() => { if (!hello && tries < 4) init(tries + 1); else if (!hello) stage('Claude never answered'); }, 2500);\n  };\n  init(1);\n})();\n</script>\n</body>\n</html>\n";
